/* Generated from research/build-process.json by tools/build-data.js — edit the JSON, then re-run. */
window.SAETA_PROCESS = {"meta":{"description":{"es":"Proceso de construcción de flechas por material, para arqueros tradicionales principiantes. Coherente con el manual del club: longitud de flecha = apertura + 2,5 cm (1 in); puntas pesadas en granos; culatín de madera siempre a contraveta.","en":"Arrow build process per shaft material, for novice traditional archers. Consistent with the club manual: arrow length = draw length + 2.5 cm (1 in); points weighed in grains; wood nock slot always across the grain."},"units":{"es":"1 gramo = 15,43 granos (gr). 1 pulgada (in) = 2,54 cm.","en":"1 gram = 15.43 grains (gr). 1 inch (in) = 2.54 cm."},"updated":"2026-11-22"},"common":{"arrowLength":{"es":"Longitud de flecha = apertura (draw length) + 2,5 cm. Se mide desde el fondo de la ranura del culatín hasta el final del astil (sin contar la punta).","en":"Arrow length = draw length + 2.5 cm (1 in). Measured from the bottom of the nock groove to the end of the shaft (point not included)."},"fletchingSteps":[{"title":{"es":"Preparar la emplumadora","en":"Set up the fletching jig"},"text":{"es":"Centra la pinza (clamp), elige recto, offset o helicoidal y fija la distancia desde el culatín (normalmente 2,5–3 cm). Ajusta el índice para 3 plumas a 120°.","en":"Centre the clamp, choose straight, offset or helical, and set the distance from the nock (usually 2.5–3 cm / 1–1.25 in). Set the index for 3 feathers at 120°."},"tip":{"es":"Haz la primera flecha completa y revísala antes de emplumar el resto con el mismo ajuste.","en":"Fletch one complete arrow and check it before doing the rest with the same setting."}},{"title":{"es":"Colocar la pluma en la pinza","en":"Load the feather in the clamp"},"text":{"es":"Mete la pluma en la pinza con la base (cañón) sobresaliendo de forma uniforme. Usa siempre plumas del mismo ala (todas izquierdas o todas derechas).","en":"Place the feather in the clamp with the base (quill) protruding evenly. Always use feathers from the same wing (all left or all right)."},"tip":{"es":"Nunca mezcles ala izquierda y derecha en una misma flecha ni en el mismo juego: giran en sentidos opuestos.","en":"Never mix left and right wing on the same arrow or set: they spin in opposite directions."}},{"title":{"es":"Encolar y apoyar","en":"Glue and seat"},"text":{"es":"Pon un cordón fino y continuo de pegamento de emplumar en la base, sin exceso, y apoya la pinza sobre el astil. Espera el tiempo que indica el pegamento (normalmente 5–15 min).","en":"Run a thin, continuous bead of fletching glue along the base, without excess, and seat the clamp on the shaft. Wait the time the glue requires (usually 5–15 min)."},"tip":{"es":"Demasiado pegamento no pega más: chorrea, ensucia y añade peso.","en":"More glue does not hold better: it drips, makes a mess and adds weight."}},{"title":{"es":"Soltar, girar y repetir","en":"Release, index and repeat"},"text":{"es":"Abre la pinza con cuidado, gira el índice a la siguiente posición y repite hasta tener las tres plumas. Al final añade una gota de pegamento en la punta delantera y trasera de cada pluma.","en":"Open the clamp gently, turn the index to the next position and repeat for all three feathers. Finish with a drop of glue at the front and rear tip of each feather."},"tip":{"es":"La pluma guía (de distinto color) debe quedar perpendicular a la ranura del culatín y alejada del arco al tirar.","en":"The cock (index) feather, usually a different colour, should sit perpendicular to the nock slot and point away from the bow when shooting."}}]},"materials":{"wood":{"name":{"es":"Madera","en":"Wood"},"summary":{"es":"Astiles de cedro (Port Orford), pino, fresno, abedul, haya, etc. Es la flecha tradicional por excelencia: barata y bonita, pero cada astil es distinto, así que hay que seleccionarlos por spine y peso, enderezarlos y sellarlos. Puntas cónicas encoladas y culatines cónicos o exteriores.","en":"Cedar (Port Orford), pine, ash, birch, beech shafts, etc. The classic traditional arrow: cheap and beautiful, but every shaft is different, so they must be sorted by spine and weight, straightened and sealed. Glue-on taper points and tapered or over nocks."},"difficulty":2,"time":{"es":"3–4 h por docena + secados (barniz y pegamentos, 1–2 días)","en":"3–4 h per dozen + drying time (finish and glues, 1–2 days)"},"tools":[{"id":"taper-tool","name":{"es":"Conificador (afilador de astiles)","en":"Taper tool"},"essential":true,"why":{"es":"Hace el cono de la punta (cuchilla larga, ~5°) y el del culatín (cuchilla corta, ~11°).","en":"Cuts the point taper (long blade, ~5°) and the nock taper (short blade, ~11°)."}},{"id":"fletching-jig","name":{"es":"Emplumadora","en":"Fletching jig"},"essential":true,"why":{"es":"Coloca las plumas siempre en la misma posición, ángulo y distancia.","en":"Places feathers in the same position, angle and distance every time."}},{"id":"grain-scale","name":{"es":"Báscula de granos","en":"Grain scale"},"essential":true,"why":{"es":"Para pesar astiles y puntas y hacer juegos homogéneos.","en":"To weigh shafts and points and build matched sets."}},{"id":"saw","name":{"es":"Sierra fina de dientes pequeños o sierra de flechas","en":"Fine-tooth saw or arrow saw"},"essential":true,"why":{"es":"Corta el astil a medida limpio y a escuadra sin astillar.","en":"Cuts the shaft to length cleanly and square without splintering."}},{"id":"tape-measure","name":{"es":"Cinta métrica y lápiz","en":"Tape measure and pencil"},"essential":true,"why":{"es":"Para marcar la longitud (apertura + 2,5 cm).","en":"To mark the length (draw length + 2.5 cm)."}},{"id":"sandpaper","name":{"es":"Lija fina (220–400) y lana de acero 0000","en":"Fine sandpaper (220–400) and 0000 steel wool"},"essential":true,"why":{"es":"Alisa el astil antes de sellar y entre capas de barniz.","en":"Smooths the shaft before sealing and between coats of finish."}},{"id":"spine-tester","name":{"es":"Medidor de spine","en":"Spine tester"},"essential":false,"why":{"es":"Mide la rigidez de cada astil. Prescindible si compras astiles ya clasificados por spine.","en":"Measures each shaft's stiffness. Optional if you buy pre-spined shafts."}},{"id":"heat-gun","name":{"es":"Pistola de calor","en":"Heat gun"},"essential":false,"why":{"es":"Ablanda la madera para enderezar curvas rebeldes.","en":"Softens the wood to straighten stubborn bends."}},{"id":"arrow-spinner","name":{"es":"Girador de flechas (spinner)","en":"Arrow spinner"},"essential":false,"why":{"es":"Comprueba que la punta gira recta y sirve para hacer cresting.","en":"Checks that the point spins true and is used for cresting."}},{"id":"dip-tube","name":{"es":"Tubo de inmersión","en":"Dip tube"},"essential":false,"why":{"es":"Para sellar o hacer crown dip sumergiendo la flecha en barniz.","en":"To seal or crown-dip by dipping the arrow in lacquer."}},{"id":"feather-burner","name":{"es":"Quemador o cortadora de plumas","en":"Feather burner or chopper"},"essential":false,"why":{"es":"Da forma y altura uniforme a las plumas (escudo, parabólica, banana).","en":"Shapes feathers to a uniform profile (shield, parabolic, banana)."}},{"id":"nock-alignment","name":{"es":"Alineador de culatines","en":"Nock alignment tool"},"essential":false,"why":{"es":"Ayuda a pegar el culatín cónico perfectamente centrado.","en":"Helps glue tapered nocks perfectly centred."}}],"consumables":[{"id":"shafts","name":{"es":"Astiles de madera","en":"Wood shafts"},"essential":true,"why":{"es":"Compra 2–4 más de los que necesites para descartar los peores.","en":"Buy 2–4 extra to discard the worst ones."}},{"id":"taper-points","name":{"es":"Puntas cónicas de encolar","en":"Glue-on taper points"},"essential":true,"why":{"es":"Mismo diámetro que el astil (5/16, 11/32 u 23/64 in) y mismo peso en granos.","en":"Same diameter as the shaft (5/16, 11/32 or 23/64 in) and same grain weight."}},{"id":"nocks","name":{"es":"Culatines cónicos o exteriores","en":"Tapered or over nocks"},"essential":true,"why":{"es":"Cónicos sobre el cono de 11°; exteriores se pegan sobre el extremo recto.","en":"Tapered nocks go on the 11° taper; over nocks glue over the straight end."}},{"id":"feathers","name":{"es":"Plumas naturales","en":"Natural feathers"},"essential":true,"why":{"es":"Todas del mismo ala; 4–5 in para tiro, 5–5,5 in para caza.","en":"All from the same wing; 4–5 in for target, 5–5.5 in for hunting."}},{"id":"fletch-glue","name":{"es":"Pegamento de emplumar (Fletch-Tite, Bohning) o cianoacrilato","en":"Fletching glue (Fletch-Tite, Bohning) or cyanoacrylate"},"essential":true,"why":{"es":"Para plumas y culatines; pega bien sobre madera sellada.","en":"For feathers and nocks; bonds well to sealed wood."}},{"id":"point-glue","name":{"es":"Epoxi bicomponente / Loctite (o termofusible)","en":"Two-part epoxy / Loctite (or hot melt)"},"essential":true,"why":{"es":"Fija la punta. La cola termofusible permite cambiar puntas mientras afinas.","en":"Secures the point. Hot melt lets you swap points while tuning."}},{"id":"sealer","name":{"es":"Sellador: barniz, laca, aceite de tung o linaza","en":"Sealer: varnish, lacquer, tung or linseed oil"},"essential":true,"why":{"es":"Protege la madera de la humedad para que no se tuerza.","en":"Protects wood from moisture so it does not warp."}},{"id":"stain","name":{"es":"Tinte para madera","en":"Wood stain"},"essential":false,"why":{"es":"Solo estético; aplícalo antes del sellador.","en":"Cosmetic only; apply before the sealer."}},{"id":"alcohol","name":{"es":"Alcohol isopropílico y trapos","en":"Isopropyl alcohol and rags"},"essential":true,"why":{"es":"Limpia grasa y polvo antes de pegar.","en":"Removes grease and dust before gluing."}},{"id":"thread","name":{"es":"Hilo para entorchado","en":"Binding thread"},"essential":false,"why":{"es":"Refuerza los extremos de las plumas y queda tradicional.","en":"Secures feather ends and looks traditional."}}],"steps":[{"title":{"es":"Inspeccionar los astiles","en":"Inspect the shafts"},"text":{"es":"Revisa cada astil a contraluz: descarta los que tengan nudos, grietas o veta que se escapa en diagonal muy marcada (runout).","en":"Check each shaft against the light: discard any with knots, cracks or strong diagonal grain runout."},"tip":{"es":"Una veta que sale muy en diagonal es un punto débil por donde puede romperse.","en":"Grain that runs out steeply is a weak spot where the shaft can break."}},{"title":{"es":"Clasificar por peso","en":"Weight-sort"},"text":{"es":"Pesa cada astil en la báscula de granos y anótalo a lápiz. Agrupa los que estén dentro de ±10 granos (un rango de 20 gr como hacen los fabricantes).","en":"Weigh each shaft on the grain scale and pencil the value on it. Group shafts within ±10 grains (a 20-grain band, as manufacturers do)."},"tip":{"es":"Pesa todos a la misma longitud; si no, compara granos por pulgada (GPI).","en":"Weigh them all at the same length; otherwise compare grains per inch (GPI)."}},{"title":{"es":"Medir el spine","en":"Spine-test"},"text":{"es":"Apoya el astil en el medidor de spine, mira la deflexión, gíralo y marca el lado más rígido. Forma juegos con un margen de 5 lb (p. ej. 45–50 lb).","en":"Place the shaft on the spine tester, read the deflection, rotate it and mark the stiffest side. Build sets within a 5 lb band (e.g. 45–50 lb)."},"tip":{"es":"Si compras astiles ya «spineados» y emparejados en peso, este paso solo es una comprobación.","en":"If you buy pre-spined, weight-matched shafts, this step is just a check."}},{"title":{"es":"Enderezar","en":"Straighten"},"text":{"es":"Mira a lo largo del astil, localiza la curva y dóblala suavemente al revés con la base de la mano, pasándote un poco. Si se resiste, caliéntala unos segundos con la pistola de calor y sujétala hasta que se enfríe.","en":"Sight down the shaft, find the bend and gently bend it the other way over the heel of your hand, slightly overcorrecting. If it resists, warm it a few seconds with a heat gun and hold it until it cools."},"tip":{"es":"Calienta poco y moviendo: si la madera se oscurece la estás quemando. Si tras tres intentos vuelve a curvarse, descártalo.","en":"Use little heat and keep moving: if the wood darkens you are scorching it. If it bends back after three tries, discard it."}},{"title":{"es":"Lijar y marcar la veta","en":"Sand and mark the grain"},"text":{"es":"Lija suave con grano fino. Decide qué extremo será el culatín y marca en él la dirección de la veta.","en":"Sand lightly with fine grit. Decide which end will be the nock and mark the grain direction on it."},"tip":{"es":"Elige para el culatín el extremo con la veta más recta y limpia.","en":"Pick the end with the straightest, cleanest grain for the nock."}},{"title":{"es":"Conificar el extremo del culatín","en":"Taper the nock end"},"text":{"es":"Con la cuchilla CORTA del conificador, gira el astil hasta que el cono quede completo y centrado. Si usas culatines exteriores, sáltate este paso.","en":"With the SHORT blade of the taper tool, turn the shaft until the taper is complete and centred. Skip this step if you use over nocks."},"tip":{"es":"Prueba el culatín en seco: debe asentar en todo el cono sin bailar ni hacer tope antes de tiempo.","en":"Dry-fit the nock: it should seat along the whole taper without wobbling or bottoming out early."}},{"title":{"es":"Teñir, sellar y decorar","en":"Stain, seal and decorate"},"text":{"es":"Aplica tinte si quieres, y después 2–3 capas de sellador (barniz, laca por inmersión o aceite), lijando con lana de acero entre capas. Haz ahora el crown dip, el cresting o los wraps.","en":"Stain if desired, then apply 2–3 coats of sealer (varnish, dipped lacquer or oil), rubbing with steel wool between coats. Do any crown dip, cresting or wraps now."},"tip":{"es":"Deja secar del todo cada capa; un barniz blando hace que las plumas se despeguen.","en":"Let each coat dry fully; soft finish makes feathers peel off."}},{"title":{"es":"Pegar el culatín a contraveta","en":"Glue the nock across the grain"},"text":{"es":"Pon pegamento en el cono y coloca el culatín con la ranura SIEMPRE perpendicular a la veta (a contraveta), nunca paralela. Gíralo un poco para repartir el pegamento y alinéalo recto.","en":"Put glue on the taper and fit the nock with its slot ALWAYS perpendicular to the grain lines, never parallel. Twist slightly to spread the glue and align it straight."},"tip":{"es":"Con la ranura paralela a la veta, la cuerda actúa como una cuña y puede rajar el astil al disparar.","en":"With the slot parallel to the grain, the string acts like a wedge and can split the shaft on release."}},{"title":{"es":"Emplumar","en":"Fletch"},"text":{"es":"Limpia la zona con alcohol y empluma con la emplumadora (normalmente helicoidal u offset para plumas naturales) a 2,5–3 cm del culatín.","en":"Wipe the area with alcohol and fletch with the jig (usually helical or offset for natural feathers) 2.5–3 cm from the nock."},"tip":{"es":"Mismo ala para todo el juego; la pluma guía alejada del arco.","en":"Same wing for the whole set; cock feather pointing away from the bow."}},{"title":{"es":"Cortar a medida","en":"Cut to length"},"text":{"es":"Marca la longitud (apertura + 2,5 cm) desde el fondo de la ranura del culatín y corta en el extremo de la punta, girando el astil para no astillarlo.","en":"Mark the length (draw length + 2.5 cm) from the bottom of the nock groove and cut at the point end, rotating the shaft to avoid splintering."},"tip":{"es":"Si vas a afinar con astil desnudo, déjalas algo largas: siempre se puede cortar, nunca alargar.","en":"If you will bare-shaft tune, leave them a bit long: you can always cut, never add."}},{"title":{"es":"Conificar la punta","en":"Taper the point end"},"text":{"es":"Con la cuchilla LARGA del conificador haz el cono de la punta (~5°) hasta que la punta encaje hasta el fondo.","en":"With the LONG blade of the taper tool cut the point taper (~5°) until the point seats fully."},"tip":{"es":"No te pases: si el cono es demasiado fino, la punta queda floja o descentrada.","en":"Do not overdo it: if the taper is too thin, the point will be loose or off-centre."}},{"title":{"es":"Pesar y pegar las puntas","en":"Weigh and glue the points"},"text":{"es":"Pesa las puntas en granos y usa el mismo peso en todo el juego. Pégalas con epoxi bicomponente o Loctite y comprueba que giran rectas.","en":"Weigh the points in grains and use the same weight for the whole set. Glue them with two-part epoxy or Loctite and check they spin true."},"tip":{"es":"Para afinar, pega las puntas de prueba con cola termofusible: se quitan calentando la punta.","en":"While tuning, fit test points with hot melt: they come off by heating the point."}},{"title":{"es":"Acabado y control final","en":"Finishing and final check"},"text":{"es":"Da forma a las plumas (quemador o tijera), haz el entorchado en los extremos si quieres, numera las flechas y haz la prueba de flexión.","en":"Shape the feathers (burner or scissors), add thread binding at the ends if desired, number the arrows and do a flex test."},"tip":{"es":"Numerar te permite detectar la flecha que siempre vuela distinta.","en":"Numbering lets you spot the arrow that always flies differently."}}],"safety":[{"es":"Nunca dispares una flecha de madera rajada o astillada: puede romperse y clavarse en la mano del arco. Haz siempre la prueba de flexión (dobla suavemente y escucha/observa crujidos).","en":"Never shoot a cracked or splintered wood arrow: it can break and pierce your bow hand. Always flex-test it (bend gently and look/listen for cracks)."},{"es":"Ventila bien al usar barnices, lacas, tintes o acetona; son inflamables. Nada de llamas cerca.","en":"Ventilate well when using varnish, lacquer, stain or acetone; they are flammable. No open flames nearby."},{"es":"Los trapos con aceite de linaza pueden autoinflamarse: extiéndelos para secar o mételos en agua.","en":"Linseed-oil rags can self-ignite: lay them flat to dry or soak them in water."},{"es":"Las cuchillas del conificador cortan mucho: gira siempre el astil, no los dedos cerca de la cuchilla.","en":"Taper-tool blades are very sharp: turn the shaft, keep fingers away from the blade."},{"es":"Usa guantes con el epoxi y el cianoacrilato; el cianoacrilato pega la piel al instante.","en":"Wear gloves with epoxy and cyanoacrylate; CA glue bonds skin instantly."},{"es":"No dispares flechas con un spine muy por debajo de tu potencia de arco: pueden romperse.","en":"Do not shoot arrows far too weak for your bow's draw weight: they can break."}],"finishing":[{"id":"sealing","name":{"es":"Sellado (barniz, laca por inmersión, aceite)","en":"Sealing (varnish, dipped lacquer, oil)"},"text":{"es":"Imprescindible en madera. La laca en tubo de inmersión da una capa uniforme; el aceite de tung o linaza es más natural pero protege menos.","en":"Essential on wood. Dip-tube lacquer gives an even coat; tung or linseed oil looks more natural but protects less."}},{"id":"stain","name":{"es":"Tinte","en":"Staining"},"text":{"es":"Oscurece o colorea la madera; siempre antes del sellador.","en":"Darkens or colours the wood; always before the sealer."}},{"id":"crown-dip","name":{"es":"Crown dip (baño de corona)","en":"Crown dip"},"text":{"es":"Se sumerge el extremo del culatín 20–25 cm en laca de color; da visibilidad y protege la zona emplumada.","en":"Dip the nock end 20–25 cm (8–10 in) in coloured lacquer; adds visibility and protects the fletching area."}},{"id":"cresting","name":{"es":"Cresting (anillos pintados)","en":"Cresting"},"text":{"es":"Anillos finos de pintura hechos con pincel mientras la flecha gira en un spinner; identifican tus flechas.","en":"Thin painted rings applied with a brush while the arrow spins in a spinner; they identify your arrows."}},{"id":"wraps","name":{"es":"Wraps (vinilos)","en":"Wraps"},"text":{"es":"Vinilos adhesivos que se enrollan en la zona de las plumas antes de emplumar.","en":"Adhesive vinyl wraps rolled onto the fletching area before fletching."}},{"id":"thread-binding","name":{"es":"Entorchado de hilo","en":"Thread binding"},"text":{"es":"Unas vueltas de hilo en los extremos de las plumas, fijadas con pegamento o barniz; evitan que se levanten.","en":"A few turns of thread at the feather ends, fixed with glue or varnish; stops them lifting."}},{"id":"feather-burning","name":{"es":"Quemado de plumas","en":"Feather burning"},"text":{"es":"Un hilo resistente caliente con la forma deseada (escudo, parabólica, banana) recorta todas las plumas igual.","en":"A heated shaped wire (shield, parabolic, banana) trims every feather identically."}},{"id":"lighted-nocks","name":{"es":"Culatines luminosos","en":"Lighted nocks"},"text":{"es":"Útiles para encontrar flechas; añaden peso atrás, así que afina con ellos puestos.","en":"Help find arrows; they add rear weight, so tune with them fitted."}}]},"bamboo":{"name":{"es":"Bambú","en":"Bamboo"},"summary":{"es":"Cañas de bambú (p. ej. bambú japonés Pseudosasa japonica o Tonkin). Ligeras, duras y muy tradicionales, pero cada caña es única: hay que secarlas, enderezarlas con calor, igualar los nudos y reforzar los extremos huecos antes de poner culatín y punta.","en":"Bamboo canes (e.g. Japanese arrow bamboo Pseudosasa japonica or Tonkin). Light, tough and very traditional, but every cane is unique: they must be dried, heat-straightened, have their nodes smoothed and their hollow ends reinforced before fitting nock and point."},"difficulty":3,"time":{"es":"6–10 h por docena repartidas en varios días (enderezado y secados)","en":"6–10 h per dozen spread over several days (straightening and drying)"},"tools":[{"id":"heat-source","name":{"es":"Pistola de calor o quemador de alcohol","en":"Heat gun or alcohol burner"},"essential":true,"why":{"es":"El bambú solo se endereza bien en caliente.","en":"Bamboo only straightens properly when hot."}},{"id":"straightening-block","name":{"es":"Taco enderezador (madera dura con muesca)","en":"Straightening block (notched hardwood)"},"essential":false,"why":{"es":"Hace palanca en los nudos sin marcarlos.","en":"Gives leverage on nodes without marking them."}},{"id":"files","name":{"es":"Lima fina y lija","en":"Fine file and sandpaper"},"essential":true,"why":{"es":"Para igualar los nudos con el resto de la caña.","en":"To level the nodes with the rest of the cane."}},{"id":"saw","name":{"es":"Sierra fina (de marquetería o japonesa)","en":"Fine saw (coping or Japanese pull saw)"},"essential":true,"why":{"es":"Corta sin abrir las fibras.","en":"Cuts without splitting the fibres."}},{"id":"grain-scale","name":{"es":"Báscula de granos","en":"Grain scale"},"essential":true,"why":{"es":"Para emparejar cañas y puntas por peso.","en":"To match canes and points by weight."}},{"id":"calipers","name":{"es":"Calibre (pie de rey)","en":"Calipers"},"essential":true,"why":{"es":"Para agrupar cañas por diámetro y elegir puntas y culatines.","en":"To group canes by diameter and choose points and nocks."}},{"id":"taper-tool","name":{"es":"Conificador","en":"Taper tool"},"essential":false,"why":{"es":"Solo si refuerzas los extremos con tacos de madera y usas puntas/culatines cónicos.","en":"Only if you plug the ends with hardwood and use taper points/nocks."}},{"id":"fletching-jig","name":{"es":"Emplumadora","en":"Fletching jig"},"essential":true,"why":{"es":"Emplumado uniforme.","en":"Consistent fletching."}},{"id":"spine-tester","name":{"es":"Medidor de spine","en":"Spine tester"},"essential":false,"why":{"es":"Muy útil: la rigidez del bambú varía mucho.","en":"Very useful: bamboo stiffness varies a lot."}}],"consumables":[{"id":"canes","name":{"es":"Cañas de bambú secas","en":"Seasoned bamboo canes"},"essential":true,"why":{"es":"Bien secas (meses) y algo más largas que la flecha; compra de sobra.","en":"Well seasoned (months) and longer than the arrow; buy extras."}},{"id":"hardwood-plugs","name":{"es":"Tacos de madera dura (varilla)","en":"Hardwood plugs (dowel)"},"essential":false,"why":{"es":"Rellenan los extremos huecos para poder conificar o reforzar.","en":"Fill the hollow ends so they can be tapered or reinforced."}},{"id":"points","name":{"es":"Puntas paralelas o cónicas de encolar","en":"Parallel or taper glue-on points"},"essential":true,"why":{"es":"Del diámetro de cada caña o del taco.","en":"Matched to each cane's or plug's diameter."}},{"id":"nocks","name":{"es":"Culatines (exteriores/cónicos) o culatín tallado","en":"Nocks (over/tapered) or self nock"},"essential":true,"why":{"es":"El culatín tallado se hace justo detrás de un nudo y se refuerza con hilo.","en":"A self nock is cut just behind a node and reinforced with thread."}},{"id":"thread","name":{"es":"Hilo (o tendón) para atar","en":"Thread (or sinew) for binding"},"essential":true,"why":{"es":"Evita que los extremos se rajen.","en":"Stops the ends from splitting."}},{"id":"epoxy","name":{"es":"Epoxi bicomponente","en":"Two-part epoxy"},"essential":true,"why":{"es":"Para tacos y puntas; rellena huecos.","en":"For plugs and points; fills gaps."}},{"id":"fletch-glue","name":{"es":"Pegamento de emplumar","en":"Fletching glue"},"essential":true,"why":{"es":"Fletch-Tite, Bohning o cianoacrilato.","en":"Fletch-Tite, Bohning or cyanoacrylate."}},{"id":"feathers","name":{"es":"Plumas naturales","en":"Natural feathers"},"essential":true,"why":{"es":"Mismo ala para todo el juego.","en":"Same wing for the whole set."}},{"id":"sealer","name":{"es":"Aceite, goma laca o barniz","en":"Oil, shellac or varnish"},"essential":false,"why":{"es":"Protege de la humedad, que hace que el bambú se tuerza.","en":"Protects against moisture, which makes bamboo warp."}}],"steps":[{"title":{"es":"Seleccionar y secar las cañas","en":"Select and season the canes"},"text":{"es":"Elige cañas rectas, sin grietas, de diámetro parecido y con nudos bien repartidos. Si son recién cortadas, déjalas secar varios meses a la sombra.","en":"Pick straight, uncracked canes of similar diameter with evenly spaced nodes. If freshly cut, let them dry for several months in the shade."},"tip":{"es":"El bambú verde se vuelve a torcer al secarse; no te saltes el secado.","en":"Green bamboo warps again as it dries; do not skip seasoning."}},{"title":{"es":"Clasificar por diámetro, peso y spine","en":"Sort by diameter, weight and spine"},"text":{"es":"Mide el diámetro con el calibre, pesa en granos y, si puedes, mide el spine. Forma juegos lo más parecidos posible.","en":"Measure diameter with calipers, weigh in grains and, if possible, spine-test. Build sets as similar as possible."},"tip":{"es":"Con bambú es normal aceptar más variación que con madera; prioriza el spine.","en":"With bamboo you accept more variation than with wood; prioritise spine."}},{"title":{"es":"Enderezar con calor","en":"Heat-straighten"},"text":{"es":"Calienta la curva moviendo la caña hasta que ceda, dóblala al revés y sujétala hasta que se enfríe. Endereza primero los tramos entre nudos y después los nudos.","en":"Heat the bend while moving the cane until it gives, bend it the opposite way and hold until cool. Straighten the internodes first, then the nodes."},"tip":{"es":"Necesitarás varias sesiones en días distintos. Si la piel se oscurece o burbujea, te has pasado de calor.","en":"Expect several sessions on different days. If the skin darkens or blisters, you used too much heat."}},{"title":{"es":"Igualar los nudos","en":"Level the nodes"},"text":{"es":"Lima y lija los nudos hasta dejarlos a ras de la caña, sin rebajar el resto de la piel.","en":"File and sand the nodes flush with the cane, without thinning the rest of the skin."},"tip":{"es":"La piel exterior brillante es la parte más fuerte; quítala lo mínimo.","en":"The glossy outer skin is the strongest part; remove as little as possible."}},{"title":{"es":"Cortar a medida pensando en los nudos","en":"Cut to length around the nodes"},"text":{"es":"Corta a apertura + 2,5 cm de modo que quede un nudo 1–3 cm por delante del culatín y, si puede ser, otro cerca de la punta. Gira la caña mientras cortas.","en":"Cut to draw length + 2.5 cm so a node sits 1–3 cm in front of the nock and, ideally, another near the point. Rotate the cane while sawing."},"tip":{"es":"Pon cinta de carrocero sobre la línea de corte para que no se abran las fibras.","en":"Put masking tape over the cut line so the fibres do not split."}},{"title":{"es":"Preparar el extremo del culatín","en":"Prepare the nock end"},"text":{"es":"O bien tallas el culatín en la propia caña (justo detrás del nudo) y lo atas con hilo y pegamento, o pegas un taco de madera dura para conificarlo y poner un culatín cónico, o usas un culatín exterior si el diámetro encaja.","en":"Either cut a self nock in the cane (just behind the node) and bind it with thread and glue, glue in a hardwood plug and taper it for a tapered nock, or use an over nock if the diameter fits."},"tip":{"es":"Orienta la ranura de modo que los nudos y la acanaladura de la caña no rocen el arco.","en":"Orient the slot so the nodes and the cane's groove do not rub the bow."}},{"title":{"es":"Reforzar y montar la punta","en":"Reinforce and fit the point"},"text":{"es":"Pega con epoxi un taco de madera dura (5–8 cm) en la boca hueca, conifícalo y pega una punta cónica; o pega directamente una punta paralela del diámetro exacto y ata hilo justo detrás.","en":"Epoxy a hardwood plug (5–8 cm) into the hollow end, taper it and glue on a taper point; or glue a parallel point of the exact diameter and bind thread just behind it."},"tip":{"es":"Pesa las puntas en granos; el taco también suma peso delante (más FOC).","en":"Weigh points in grains; the plug also adds front weight (more FOC)."}},{"title":{"es":"Sellar","en":"Seal"},"text":{"es":"Da aceite, goma laca o barniz fino, sobre todo en los extremos cortados y las ataduras.","en":"Apply oil, shellac or thin varnish, especially on cut ends and bindings."},"tip":{"es":"Lija muy suave la zona de las plumas para que el pegamento agarre.","en":"Lightly sand the fletching area so the glue grips."}},{"title":{"es":"Emplumar y atar","en":"Fletch and bind"},"text":{"es":"Empluma con la emplumadora como en madera y remata los extremos de las plumas con entorchado de hilo.","en":"Fletch with the jig as for wood and finish the feather ends with thread binding."},"tip":{"es":"En bambú el entorchado es casi obligatorio: la superficie es lisa y las plumas se levantan con facilidad.","en":"On bamboo binding is almost a must: the surface is slick and feathers lift easily."}},{"title":{"es":"Control final","en":"Final check"},"text":{"es":"Comprueba rectitud, peso total y la ausencia de grietas, sobre todo junto a los nudos. Vuelve a enderezar si hace falta.","en":"Check straightness, total weight and look for cracks, especially beside nodes. Re-straighten if needed."},"tip":{"es":"El bambú se mueve con la humedad: revisa la rectitud antes de cada sesión.","en":"Bamboo moves with humidity: check straightness before each session."}}],"safety":[{"es":"El bambú astillado tiene bordes muy cortantes: usa guantes al lijar y revisa grietas antes de tirar.","en":"Split bamboo has razor-sharp edges: wear gloves when sanding and check for cracks before shooting."},{"es":"Nunca dispares una caña rajada, sobre todo si la grieta está junto a un nudo o en el culatín.","en":"Never shoot a cracked cane, especially if the crack is near a node or the nock."},{"es":"Cuidado con la llama y la pistola de calor: quemaduras y riesgo de incendio. Trabaja sobre superficie no inflamable.","en":"Take care with flame and heat gun: burns and fire risk. Work on a non-flammable surface."},{"es":"Ventila al usar barnices y disolventes.","en":"Ventilate when using varnish and solvents."}],"finishing":[{"id":"flame-toning","name":{"es":"Tostado con llama","en":"Flame toning"},"text":{"es":"Pasar la llama con cuidado oscurece la caña en tonos dorados; además ayuda a endurecer la piel.","en":"Passing a flame carefully browns the cane to golden tones and helps harden the skin."}},{"id":"sealing","name":{"es":"Aceite o goma laca","en":"Oil or shellac"},"text":{"es":"Protege de la humedad y realza el color natural.","en":"Protects from moisture and brings out the natural colour."}},{"id":"thread-binding","name":{"es":"Entorchado de hilo o tendón","en":"Thread or sinew binding"},"text":{"es":"En culatín, punta y extremos de las plumas: refuerza y decora.","en":"At nock, point and feather ends: reinforces and decorates."}},{"id":"cresting","name":{"es":"Cresting","en":"Cresting"},"text":{"es":"Anillos pintados entre nudos para identificar las flechas.","en":"Painted rings between nodes to identify arrows."}},{"id":"feather-burning","name":{"es":"Quemado de plumas","en":"Feather burning"},"text":{"es":"Perfil escudo o parabólico bajo queda muy bien en bambú.","en":"A low shield or parabolic profile suits bamboo well."}}]},"carbon":{"name":{"es":"Carbono (tradicional, incluido carbono con aspecto madera y con footing)","en":"Carbon (traditional, including wood-look and footed carbon)"},"summary":{"es":"Tubos de carbono pensados para arco tradicional, a veces con acabado imitación madera o con un refuerzo (footing) en la punta. Son muy constantes y resistentes: no hay que enderezar ni sellar. El trabajo es cortar bien, pegar insertos/puntas y culatines, y emplumar.","en":"Carbon tubes made for traditional bows, sometimes with a wood-grain finish or a reinforcing footing at the point. Very consistent and durable: no straightening or sealing. The work is clean cutting, gluing inserts/points and nocks, and fletching."},"difficulty":1,"time":{"es":"1,5–2 h por docena + curado del pegamento (hasta 24 h con epoxi)","en":"1.5–2 h per dozen + glue cure (up to 24 h with epoxy)"},"tools":[{"id":"arrow-saw","name":{"es":"Sierra de flechas (disco abrasivo de alta velocidad)","en":"Arrow saw (high-speed abrasive wheel)"},"essential":true,"why":{"es":"Es el único método que dan los fabricantes para cortar carbono limpio y a escuadra. Una minitaladradora con disco y guía puede servir.","en":"The only method manufacturers recommend for a clean, square carbon cut. A rotary tool with cut-off disc and a guide can work."}},{"id":"squaring-tool","name":{"es":"Escuadrador / desbarbador","en":"Squaring / deburring tool"},"essential":true,"why":{"es":"Deja el extremo plano y sin fibras para que el inserto asiente recto.","en":"Leaves the end flat and fibre-free so the insert seats straight."}},{"id":"fletching-jig","name":{"es":"Emplumadora","en":"Fletching jig"},"essential":true,"why":{"es":"Emplumado uniforme.","en":"Consistent fletching."}},{"id":"grain-scale","name":{"es":"Báscula de granos","en":"Grain scale"},"essential":true,"why":{"es":"Para pesar puntas y comprobar el peso total y el FOC.","en":"To weigh points and check total weight and FOC."}},{"id":"heat-source","name":{"es":"Mechero, quemador o pistola de calor","en":"Lighter, burner or heat gun"},"essential":false,"why":{"es":"Solo si usas cola termofusible; se calienta la punta, nunca el tubo.","en":"Only if you use hot melt; heat the point, never the tube."}},{"id":"arrow-spinner","name":{"es":"Girador de flechas","en":"Arrow spinner"},"essential":false,"why":{"es":"Comprueba que punta y culatín están rectos.","en":"Checks that point and nock run true."}},{"id":"mask-gloves","name":{"es":"Mascarilla FFP2, gafas y guantes","en":"FFP2/N95 mask, glasses and gloves"},"essential":true,"why":{"es":"El polvo y las astillas de carbono irritan piel y pulmones.","en":"Carbon dust and splinters irritate skin and lungs."}}],"consumables":[{"id":"shafts","name":{"es":"Tubos de carbono","en":"Carbon shafts"},"essential":true,"why":{"es":"Del spine correcto para tu potencia y longitud (tabla del fabricante).","en":"Of the correct spine for your draw weight and length (maker's chart)."}},{"id":"inserts-points","name":{"es":"Insertos y puntas (roscadas o de encolar)","en":"Inserts and points (screw-in or glue-in)"},"essential":true,"why":{"es":"Del diámetro interior exacto del tubo.","en":"Matching the tube's exact inside diameter."}},{"id":"nocks","name":{"es":"Culatines (a presión, pin u over)","en":"Nocks (press-fit, pin or over)"},"essential":true,"why":{"es":"Los de presión entran sin pegamento o con una gota.","en":"Press-fit nocks go in without glue or with one drop."}},{"id":"point-glue","name":{"es":"Termofusible de baja temperatura o epoxi para insertos","en":"Low-temperature hot melt or insert epoxy"},"essential":true,"why":{"es":"Sigue al fabricante del tubo: algunos (Easton, Gold Tip) piden epoxi/adhesivo propio y no termofusible.","en":"Follow the shaft maker: some (Easton, Gold Tip) require epoxy/their own adhesive, not hot melt."}},{"id":"footing","name":{"es":"Footing / outsert / half-out","en":"Footing / outsert / half-out"},"essential":false,"why":{"es":"Refuerzo de aluminio, latón o madera en la punta: más durabilidad y FOC.","en":"Aluminium, brass or wood reinforcement at the point: more durability and FOC."}},{"id":"fletching","name":{"es":"Plumas naturales o vanes","en":"Natural feathers or vanes"},"essential":true,"why":{"es":"Plumas para disparar desde la repisa; vanes solo con reposaflechas elevado.","en":"Feathers for shooting off the shelf; vanes only with a raised rest."}},{"id":"fletch-glue","name":{"es":"Pegamento de emplumar o cianoacrilato","en":"Fletching glue or cyanoacrylate"},"essential":true,"why":{"es":"Fletch-Tite, Bohning, o un cianoacrilato apto para carbono.","en":"Fletch-Tite, Bohning, or a carbon-friendly cyanoacrylate."}},{"id":"alcohol","name":{"es":"Alcohol isopropílico (≥90 %) y bastoncillos","en":"Isopropyl alcohol (≥90%) and cotton swabs"},"essential":true,"why":{"es":"Limpia polvo de corte y grasa antes de pegar.","en":"Removes cutting dust and grease before gluing."}},{"id":"wraps","name":{"es":"Wraps","en":"Wraps"},"essential":false,"why":{"es":"Dan una buena superficie para pegar y facilitan cambiar plumas.","en":"Provide a good gluing surface and make re-fletching easier."}}],"steps":[{"title":{"es":"Elegir spine y medir","en":"Choose spine and measure"},"text":{"es":"Elige el spine con la tabla del fabricante (potencia, longitud y peso de punta). Longitud = apertura + 2,5 cm.","en":"Pick the spine from the maker's chart (draw weight, length and point weight). Length = draw length + 2.5 cm."},"tip":{"es":"Cuanto más cortes, más rígida será la flecha.","en":"The more you cut, the stiffer the arrow becomes."}},{"title":{"es":"Marcar la longitud","en":"Mark the length"},"text":{"es":"Con el culatín puesto, mide desde el fondo de la ranura hasta el extremo del tubo (sin inserto ni punta) y marca todo el contorno.","en":"With the nock fitted, measure from the bottom of the nock groove to the end of the tube (no insert or point) and mark all the way round."},"tip":{"es":"En flechas con footing, recuerda que el outsert sobresale y suma longitud.","en":"With footed arrows, remember the outsert sticks out and adds length."}},{"title":{"es":"Cortar","en":"Cut"},"text":{"es":"Corta con la sierra de flechas girando el tubo despacio contra el disco, sin forzar. Corta primero una, compruébala a plena apertura y luego corta el resto.","en":"Cut with the arrow saw, rotating the tube slowly against the wheel, without forcing it. Cut one first, check it at full draw, then cut the rest."},"tip":{"es":"Nunca cortes carbono con sierra de dientes o cortatubos: astilla y raja las fibras.","en":"Never cut carbon with a toothed saw or tube cutter: it splinters and cracks the fibres."}},{"title":{"es":"Escuadrar y limpiar","en":"Square and clean"},"text":{"es":"Pasa el escuadrador por el extremo y limpia el interior (unos 2,5 cm) con un bastoncillo con alcohol. Deja secar.","en":"Run the squaring tool over the end and clean the inside (about 2.5 cm / 1 in) with an alcohol swab. Let it dry."},"tip":{"es":"No sumerjas el tubo en disolventes ni uses acetona con los culatines puestos.","en":"Do not soak the tube in solvents or use acetone with the nocks fitted."}},{"title":{"es":"Probar en seco","en":"Dry-fit"},"text":{"es":"Prueba inserto, punta, footing y culatín sin pegamento: deben entrar justos pero sin forzar.","en":"Test-fit insert, point, footing and nock without glue: snug but not forced."},"tip":{"es":"Un inserto forzado puede delaminar el tubo. Si no entra, revisa que el extremo no se haya abierto al cortar.","en":"A forced insert can delaminate the tube. If it will not go in, check the end did not flare when cutting."}},{"title":{"es":"Pegar inserto o punta","en":"Glue the insert or point"},"text":{"es":"Con termofusible: calienta la punta (no el tubo), pon cola dentro del tubo y en la punta e introdúcela rápido girándola hasta el tope; quita el sobrante antes de que endurezca. Con epoxi: unta el inserto, introdúcelo girando una vuelta, limpia y deja curar.","en":"With hot melt: heat the point (not the tube), put glue inside the tube and on the point, push it in quickly with a twist until it seats; wipe off excess before it sets. With epoxy: coat the insert, push it in with one full turn, wipe and let cure."},"tip":{"es":"Si la punta quema al tocarla, está demasiado caliente para el carbono. Con epoxi espera 24 h antes de tirar.","en":"If the point is too hot to hold, it is too hot for carbon. With epoxy wait 24 h before shooting."}},{"title":{"es":"Montar el footing (opcional)","en":"Fit the footing (optional)"},"text":{"es":"En flechas con footing, pega el outsert o half-out sobre/en la punta del tubo con epoxi, bien asentado y recto.","en":"On footed arrows, epoxy the outsert or half-out over/into the tube tip, fully seated and straight."},"tip":{"es":"El footing protege la punta del tubo de astillarse y sube el FOC; pésalo y cuéntalo en el peso total.","en":"Footing stops the tube tip splitting and raises FOC; weigh it and include it in total weight."}},{"title":{"es":"Poner los culatines","en":"Fit the nocks"},"text":{"es":"Culatín interior: presiona hasta el tope (como mucho una gota de pegamento). Pin: pega el casquillo y encaja el culatín. Exterior (over): pégalo sobre el tubo.","en":"Inside nock: press in fully (at most one drop of glue). Pin: glue in the bushing and snap on the nock. Over nock: glue it over the tube."},"tip":{"es":"Usa la mano o una herramienta, nunca alicates. Orienta todos los culatines igual.","en":"Use your hand or a nock tool, never pliers. Orient all nocks the same way."}},{"title":{"es":"Preparar la zona de emplumar","en":"Prep the fletching area"},"text":{"es":"Limpia con alcohol hasta que el papel salga limpio. Para vanes, lija muy suave con estropajo fino. Pon wraps ahora si los usas.","en":"Wipe with alcohol until the towel comes away clean. For vanes, scuff very lightly with a fine pad. Apply wraps now if using them."},"tip":{"es":"En carbono con acabado madera no lijes: atravesarías el estampado. Basta con alcohol.","en":"On wood-look carbon do not scuff: you would go through the print. Alcohol is enough."}},{"title":{"es":"Emplumar","en":"Fletch"},"text":{"es":"Empluma con la emplumadora (helicoidal u offset para plumas) a 2,5–3 cm del culatín.","en":"Fletch with the jig (helical or offset for feathers) 2.5–3 cm from the nock."},"tip":{"es":"Con plumas y tiro desde la repisa, la pluma guía va hacia fuera del arco.","en":"With feathers off the shelf, the cock feather points away from the bow."}},{"title":{"es":"Comprobar y numerar","en":"Check and number"},"text":{"es":"Gira cada flecha en el spinner, pésala, flexiónala y numérala.","en":"Spin each arrow, weigh it, flex it and number it."},"tip":{"es":"Si una punta oscila al girar, recalienta (termofusible) y recoloca.","en":"If a point wobbles when spun, reheat (hot melt) and reseat it."}}],"safety":[{"es":"Corta el carbono con mascarilla FFP2, gafas y guantes; aspira el polvo, no lo soples.","en":"Cut carbon with an FFP2/N95 mask, glasses and gloves; vacuum the dust, do not blow it."},{"es":"Haz la prueba de flexión y crujido tras cada impacto fuerte: un carbono dañado puede romperse al soltar y clavarse en la mano o el brazo. Nunca dispares una flecha agrietada.","en":"Do the flex-and-crackle test after any hard impact: damaged carbon can shatter on release and drive into your hand or arm. Never shoot a cracked arrow."},{"es":"Nunca apliques llama ni calor alto al tubo de carbono; calienta solo la punta.","en":"Never put flame or high heat on a carbon tube; heat only the point."},{"es":"No dispares flechas más cortas que la apertura: la punta podría caer detrás del arco.","en":"Do not shoot arrows shorter than your draw: the point could fall behind the bow."},{"es":"Deja curar del todo el pegamento del inserto antes de tirar.","en":"Let insert glue fully cure before shooting."}],"finishing":[{"id":"wraps","name":{"es":"Wraps","en":"Wraps"},"text":{"es":"La decoración más fácil en carbono; mejoran el agarre de las plumas.","en":"The easiest decoration on carbon; improves feather adhesion."}},{"id":"thread-binding","name":{"es":"Entorchado de hilo","en":"Thread binding"},"text":{"es":"Da aspecto tradicional y sujeta los extremos de las plumas.","en":"Gives a traditional look and secures feather ends."}},{"id":"footing","name":{"es":"Footing de madera o metal","en":"Wood or metal footing"},"text":{"es":"Refuerza la punta y da un aspecto clásico.","en":"Reinforces the point and gives a classic look."}},{"id":"feather-burning","name":{"es":"Quemado de plumas","en":"Feather burning"},"text":{"es":"Forma uniforme de las plumas.","en":"Uniform feather profile."}},{"id":"lighted-nocks","name":{"es":"Culatines luminosos","en":"Lighted nocks"},"text":{"es":"Fáciles de encontrar; afina con ellos puestos.","en":"Easy to find; tune with them fitted."}}]},"fiberglass":{"name":{"es":"Fibra de vidrio","en":"Fiberglass"},"summary":{"es":"Astiles macizos o tubulares de fibra de vidrio. Baratos, resistentes y muy usados en escuelas y para principiantes; más pesados que el carbono. Se montan casi como el carbono, con especial cuidado al cortar por el polvo de vidrio.","en":"Solid or tubular fiberglass shafts. Cheap, tough and common in schools and for beginners; heavier than carbon. Built much like carbon, with extra care when cutting because of glass dust."},"difficulty":1,"time":{"es":"1,5–2 h por docena + curado del pegamento","en":"1.5–2 h per dozen + glue cure"},"tools":[{"id":"arrow-saw","name":{"es":"Sierra de flechas o sierra fina de metal","en":"Arrow saw or fine hacksaw"},"essential":true,"why":{"es":"Corte limpio; con sierra de metal, cinta en la línea de corte.","en":"Clean cut; with a hacksaw, tape the cut line."}},{"id":"squaring-tool","name":{"es":"Escuadrador o lija sobre taco","en":"Squaring tool or sandpaper on a block"},"essential":true,"why":{"es":"Deja el extremo plano y sin fibras sueltas.","en":"Leaves the end flat with no loose fibres."}},{"id":"fletching-jig","name":{"es":"Emplumadora","en":"Fletching jig"},"essential":true,"why":{"es":"Emplumado uniforme.","en":"Consistent fletching."}},{"id":"grain-scale","name":{"es":"Báscula de granos","en":"Grain scale"},"essential":false,"why":{"es":"Para igualar puntas y pesos.","en":"To match points and weights."}},{"id":"mask-gloves","name":{"es":"Mascarilla FFP2, gafas y guantes","en":"FFP2/N95 mask, glasses and gloves"},"essential":true,"why":{"es":"Las fibras de vidrio pican y no deben respirarse.","en":"Glass fibres itch and must not be inhaled."}}],"consumables":[{"id":"shafts","name":{"es":"Astiles de fibra de vidrio","en":"Fiberglass shafts"},"essential":true,"why":{"es":"Macizos (más baratos y pesados) o tubulares.","en":"Solid (cheaper, heavier) or tubular."}},{"id":"points","name":{"es":"Puntas: paralelas de encolar (macizos) o insertos/puntas interiores (tubulares)","en":"Points: parallel glue-on (solid) or inserts/glue-in points (tubular)"},"essential":true,"why":{"es":"Del diámetro exacto del astil.","en":"Matching the exact shaft diameter."}},{"id":"nocks","name":{"es":"Culatines exteriores (macizos) o interiores (tubulares)","en":"Over nocks (solid) or inside nocks (tubular)"},"essential":true,"why":{"es":"Según el tipo de astil.","en":"Depending on shaft type."}},{"id":"glue","name":{"es":"Epoxi o termofusible; pegamento de emplumar","en":"Epoxy or hot melt; fletching glue"},"essential":true,"why":{"es":"Epoxi para puntas exteriores; termofusible para puntas interiores.","en":"Epoxy for over-fitting points; hot melt for glue-in points."}},{"id":"fletching","name":{"es":"Plumas o vanes","en":"Feathers or vanes"},"essential":true,"why":{"es":"Plumas si tiras desde la repisa.","en":"Feathers if shooting off the shelf."}},{"id":"alcohol","name":{"es":"Alcohol isopropílico","en":"Isopropyl alcohol"},"essential":true,"why":{"es":"Limpieza antes de pegar.","en":"Cleaning before gluing."}},{"id":"masking-tape","name":{"es":"Cinta de carrocero","en":"Masking tape"},"essential":false,"why":{"es":"Evita que el corte se deshilache.","en":"Stops the cut from fraying."}}],"steps":[{"title":{"es":"Identificar el tipo de astil","en":"Identify the shaft type"},"text":{"es":"Mira si es macizo o tubular: eso decide qué puntas y culatines usar.","en":"Check whether it is solid or tubular: that decides which points and nocks to use."},"tip":{"es":"Mide el diámetro con calibre antes de comprar componentes.","en":"Measure the diameter with calipers before buying components."}},{"title":{"es":"Medir y marcar","en":"Measure and mark"},"text":{"es":"Longitud = apertura + 2,5 cm, medida desde el fondo de la ranura del culatín. Marca todo el contorno y pon cinta encima.","en":"Length = draw length + 2.5 cm, measured from the bottom of the nock groove. Mark all the way round and tape over it."},"tip":{"es":"Para niños en crecimiento, deja algo más de margen.","en":"For growing children, leave a little extra length."}},{"title":{"es":"Cortar","en":"Cut"},"text":{"es":"Corta con sierra de flechas o sierra de metal fina, girando el astil y sin forzar.","en":"Cut with an arrow saw or fine hacksaw, rotating the shaft and without forcing."},"tip":{"es":"Corta con mascarilla y, si puedes, en exterior; humedecer la zona reduce el polvo.","en":"Cut wearing a mask and, if possible, outdoors; dampening the area reduces dust."}},{"title":{"es":"Escuadrar y limpiar","en":"Square and clean"},"text":{"es":"Escuadra el extremo, elimina fibras sueltas y limpia con alcohol.","en":"Square the end, remove loose fibres and clean with alcohol."},"tip":{"es":"Una fibra suelta en el extremo es el inicio de una raja.","en":"A loose fibre at the end is where a split starts."}},{"title":{"es":"Montar la punta","en":"Fit the point"},"text":{"es":"Macizo: pega una punta paralela por fuera con epoxi. Tubular: pega el inserto o punta interior con termofusible (calentando la punta) o epoxi.","en":"Solid: epoxy a parallel point over the end. Tubular: glue the insert or glue-in point with hot melt (heating the point) or epoxy."},"tip":{"es":"Lija ligeramente el extremo antes del epoxi para que agarre mejor.","en":"Lightly scuff the end before epoxy so it grips better."}},{"title":{"es":"Poner el culatín","en":"Fit the nock"},"text":{"es":"Macizo: culatín exterior pegado. Tubular: culatín interior a presión. Alinea todos igual.","en":"Solid: glued over nock. Tubular: press-fit inside nock. Align them all the same way."},"tip":{"es":"Comprueba que la cuerda entra con un «clic» suave en el culatín, ni flojo ni duro.","en":"Check the string clicks gently into the nock, neither loose nor tight."}},{"title":{"es":"Preparar y emplumar","en":"Prep and fletch"},"text":{"es":"Limpia la zona con alcohol (lija suave si usas vanes) y empluma a 2,5–3 cm del culatín.","en":"Wipe the area with alcohol (light scuff for vanes) and fletch 2.5–3 cm from the nock."},"tip":{"es":"Para principiantes, plumas de 4 in en emplumado offset son una buena elección.","en":"For beginners, 4 in feathers fletched offset are a good choice."}},{"title":{"es":"Revisar","en":"Inspect"},"text":{"es":"Busca fibras levantadas o grietas a lo largo del astil, sobre todo tras golpes laterales.","en":"Look for lifted fibres or cracks along the shaft, especially after side impacts."},"tip":{"es":"La fibra de vidrio se astilla si recibe un impacto lateral (p. ej. otra flecha).","en":"Fiberglass splinters if hit from the side (e.g. by another arrow)."}}],"safety":[{"es":"El polvo y las astillas de fibra de vidrio irritan piel, ojos y pulmones: mascarilla FFP2, gafas y guantes al cortar y lijar.","en":"Fiberglass dust and splinters irritate skin, eyes and lungs: FFP2/N95 mask, glasses and gloves when cutting and sanding."},{"es":"Desecha cualquier astil con fibras levantadas o grietas; puede astillarse al disparar.","en":"Discard any shaft with lifted fibres or cracks; it can splinter when shot."},{"es":"No calientes en exceso el astil: la resina puede ablandarse.","en":"Do not overheat the shaft: the resin can soften."},{"es":"Lava la ropa de trabajo por separado.","en":"Wash work clothes separately."}],"finishing":[{"id":"wraps","name":{"es":"Wraps","en":"Wraps"},"text":{"es":"Decoración e identificación rápidas.","en":"Quick decoration and identification."}},{"id":"cresting","name":{"es":"Cresting","en":"Cresting"},"text":{"es":"Posible con pintura apta para plásticos tras limpiar con alcohol.","en":"Possible with paint suitable for plastics after an alcohol wipe."}},{"id":"thread-binding","name":{"es":"Entorchado","en":"Thread binding"},"text":{"es":"Sujeta los extremos de las plumas.","en":"Secures feather ends."}},{"id":"name-label","name":{"es":"Nombre o número","en":"Name or number"},"text":{"es":"Muy útil en clubs con flechas de escuela.","en":"Very useful in clubs with shared arrows."}}]},"aluminium":{"name":{"es":"Aluminio","en":"Aluminium"},"summary":{"es":"Tubos de aluminio (p. ej. 1916, 2016…). Muy uniformes en peso y spine, fáciles de montar y de reparar; se pueden doblar pero también volver a enderezar. Cola termofusible para insertos y culatines cónicos sobre el extremo estampado (swage) o culatines a presión.","en":"Aluminium tubes (e.g. 1916, 2016…). Very consistent in weight and spine, easy to build and repair; they can bend but can also be straightened. Hot melt for inserts, and conventional nocks on the swaged taper or press-fit nocks."},"difficulty":1,"time":{"es":"1,5–2 h por docena + secado del pegamento","en":"1.5–2 h per dozen + glue drying"},"tools":[{"id":"arrow-saw","name":{"es":"Sierra de flechas (disco abrasivo)","en":"Arrow saw (abrasive wheel)"},"essential":true,"why":{"es":"Corte recto sin aplastar el tubo.","en":"Square cut without crushing the tube."}},{"id":"deburr","name":{"es":"Escuadrador / desbarbador","en":"Squaring / deburring tool"},"essential":true,"why":{"es":"Quita la rebaba interior y exterior.","en":"Removes inside and outside burrs."}},{"id":"heat-source","name":{"es":"Quemador de alcohol o butano","en":"Alcohol or butane burner"},"essential":true,"why":{"es":"Para calentar insertos/puntas y la barra de termofusible.","en":"To heat inserts/points and the hot-melt stick."}},{"id":"fletching-jig","name":{"es":"Emplumadora","en":"Fletching jig"},"essential":true,"why":{"es":"Emplumado uniforme.","en":"Consistent fletching."}},{"id":"grain-scale","name":{"es":"Báscula de granos","en":"Grain scale"},"essential":false,"why":{"es":"Para puntas y peso total.","en":"For points and total weight."}},{"id":"straightener","name":{"es":"Enderezador de flechas","en":"Arrow straightener"},"essential":false,"why":{"es":"Detecta y corrige curvas tras golpes.","en":"Finds and corrects bends after impacts."}}],"consumables":[{"id":"shafts","name":{"es":"Tubos de aluminio","en":"Aluminium shafts"},"essential":true,"why":{"es":"Elige el tamaño con la tabla de spine del fabricante.","en":"Choose the size from the maker's spine chart."}},{"id":"inserts-points","name":{"es":"Insertos (p. ej. RPS) y puntas, o puntas de encolar","en":"Inserts (e.g. RPS) and points, or glue-in points"},"essential":true,"why":{"es":"Del tamaño del tubo (p. ej. 2016).","en":"Matching the tube size (e.g. 2016)."}},{"id":"nocks","name":{"es":"Culatines cónicos (swage) o a presión (con casquillo)","en":"Conventional (swage) or press-fit nocks (with bushing)"},"essential":true,"why":{"es":"Según el extremo del tubo.","en":"Depending on the tube's nock end."}},{"id":"hot-melt","name":{"es":"Barra de termofusible (Ferr-L-Tite, Easton)","en":"Hot-melt stick (Ferr-L-Tite, Easton)"},"essential":true,"why":{"es":"El pegamento estándar para insertos en aluminio.","en":"The standard insert glue for aluminium."}},{"id":"fletch-glue","name":{"es":"Pegamento de emplumar","en":"Fletching glue"},"essential":true,"why":{"es":"Para plumas y culatines cónicos.","en":"For feathers and conventional nocks."}},{"id":"solvent","name":{"es":"Alcohol isopropílico o MEK","en":"Isopropyl alcohol or MEK"},"essential":true,"why":{"es":"Desengrasa la zona de las plumas.","en":"Degreases the fletching area."}},{"id":"fletching","name":{"es":"Plumas o vanes","en":"Feathers or vanes"},"essential":true,"why":{"es":"Plumas para tiro desde la repisa.","en":"Feathers for shooting off the shelf."}}],"steps":[{"title":{"es":"Elegir el tubo y medir","en":"Choose the tube and measure"},"text":{"es":"Elige el tamaño (p. ej. 1916) con la tabla del fabricante. Longitud = apertura + 2,5 cm, desde el fondo de la ranura del culatín hasta el extremo del tubo.","en":"Pick the size (e.g. 1916) from the maker's chart. Length = draw length + 2.5 cm, from the bottom of the nock groove to the end of the tube."},"tip":{"es":"En aluminio los dos primeros dígitos son el diámetro en 64avos de pulgada y los dos últimos el grosor de pared en milésimas.","en":"In aluminium sizes the first two digits are the diameter in 64ths of an inch and the last two the wall thickness in thousandths."}},{"title":{"es":"Cortar","en":"Cut"},"text":{"es":"Corta con la sierra de flechas girando el tubo. Corta una, pruébala y luego el resto.","en":"Cut with the arrow saw while rotating the tube. Cut one, test it, then the rest."},"tip":{"es":"Evita el cortatubos de fontanero: estrecha el extremo y el inserto no entra bien.","en":"Avoid a plumber's tube cutter: it crimps the end and the insert will not fit well."}},{"title":{"es":"Desbarbar y limpiar","en":"Deburr and clean"},"text":{"es":"Quita la rebaba por dentro y por fuera y limpia el interior con un bastoncillo con alcohol.","en":"Remove burrs inside and out and clean the inside with an alcohol swab."},"tip":{"es":"Una rebaba interior impide que el inserto asiente recto.","en":"An inside burr stops the insert seating straight."}},{"title":{"es":"Pegar el inserto o la punta","en":"Glue the insert or point"},"text":{"es":"Calienta el inserto con la punta enroscada, derrite termofusible sobre él (y un poco dentro del tubo), introdúcelo girando hasta el tope y limpia el sobrante en caliente.","en":"Heat the insert with the point screwed on, melt hot melt onto it (and a little inside the tube), push it in with a twist until it seats and wipe excess while warm."},"tip":{"es":"Calienta el componente, no el tubo; el exceso de calor puede debilitar el aluminio.","en":"Heat the component, not the tube; excess heat can weaken the aluminium."}},{"title":{"es":"Poner los culatines","en":"Fit the nocks"},"text":{"es":"Extremo cónico estampado (swage): pega el culatín cónico con pegamento de emplumar, recto y orientado. Con casquillo (uni-bushing): culatín a presión.","en":"Swaged taper: glue the conventional nock on with fletching glue, straight and indexed. With a bushing (uni-bushing): press-fit nock."},"tip":{"es":"No uses acetona ni MEK con los culatines ya puestos: los dañan.","en":"Do not use acetone or MEK once nocks are fitted: it damages them."}},{"title":{"es":"Preparar la zona de emplumar","en":"Prep the fletching area"},"text":{"es":"Limpia con alcohol o MEK hasta que no quede residuo. Para vanes, lija muy suave.","en":"Wipe with alcohol or MEK until no residue shows. For vanes, scuff very lightly."},"tip":{"es":"Toca la zona limpia lo menos posible: la grasa de los dedos estropea el pegado.","en":"Touch the cleaned area as little as possible: finger grease spoils adhesion."}},{"title":{"es":"Emplumar","en":"Fletch"},"text":{"es":"Empluma con la emplumadora a 2,5–3 cm del culatín.","en":"Fletch with the jig 2.5–3 cm from the nock."},"tip":{"es":"Mismo ala y misma orientación de la pluma guía en todo el juego.","en":"Same wing and same cock-feather orientation for the whole set."}},{"title":{"es":"Comprobar rectitud","en":"Check straightness"},"text":{"es":"Haz girar cada flecha sobre la mesa o en un enderezador; corrige las curvas antes de cada sesión.","en":"Roll each arrow on a table or in a straightener; correct bends before every session."},"tip":{"es":"Una flecha con un pliegue marcado (no una curva suave) debe desecharse.","en":"An arrow with a sharp kink (not a gentle bend) should be discarded."}}],"safety":[{"es":"Usa gafas al cortar: saltan partículas de metal y del disco.","en":"Wear glasses when cutting: metal and wheel particles fly off."},{"es":"Cuidado con las quemaduras: el inserto y el termofusible queman.","en":"Beware of burns: the insert and hot melt get very hot."},{"es":"Nunca dispares una flecha con un pliegue, abolladura o grieta; revisa tras cada impacto contra algo duro.","en":"Never shoot an arrow with a kink, dent or crack; check after any hit on something hard."},{"es":"Ventila al usar MEK, acetona o lacas.","en":"Ventilate when using MEK, acetone or lacquers."}],"finishing":[{"id":"crown-dip","name":{"es":"Crown dip","en":"Crown dip"},"text":{"es":"Posible tras desengrasar bien; mejora la visibilidad.","en":"Possible after thorough degreasing; improves visibility."}},{"id":"cresting","name":{"es":"Cresting","en":"Cresting"},"text":{"es":"Anillos de pintura con el spinner; usa pintura apta para metal.","en":"Painted rings on the spinner; use paint suitable for metal."}},{"id":"wraps","name":{"es":"Wraps","en":"Wraps"},"text":{"es":"La forma más sencilla de decorar e identificar.","en":"The simplest way to decorate and identify."}},{"id":"thread-binding","name":{"es":"Entorchado","en":"Thread binding"},"text":{"es":"Sujeta los extremos de las plumas.","en":"Secures feather ends."}},{"id":"lighted-nocks","name":{"es":"Culatines luminosos","en":"Lighted nocks"},"text":{"es":"Requieren casquillo compatible.","en":"Require a compatible bushing."}}]}},"glueGuide":[{"use":{"es":"Plumas naturales","en":"Natural feathers"},"glue":{"es":"Pegamento de emplumar (Fletch-Tite, Bohning Fletch-Tite Platinum) o cianoacrilato en gel","en":"Fletching cement (Fletch-Tite, Bohning Fletch-Tite Platinum) or gel cyanoacrylate"}},{"use":{"es":"Vanes de plástico","en":"Plastic vanes"},"glue":{"es":"Cianoacrilato apto para vanes o Fletch-Tite Platinum; superficie limpia y lijada suave","en":"Vane-rated cyanoacrylate or Fletch-Tite Platinum; clean, lightly scuffed surface"}},{"use":{"es":"Puntas en madera y bambú","en":"Points on wood and bamboo"},"glue":{"es":"Epoxi bicomponente / Loctite (fijo) o termofusible (desmontable, ideal para afinar)","en":"Two-part epoxy / Loctite (permanent) or hot melt (removable, ideal while tuning)"}},{"use":{"es":"Insertos en aluminio","en":"Inserts in aluminium"},"glue":{"es":"Termofusible (Ferr-L-Tite, Easton)","en":"Hot melt (Ferr-L-Tite, Easton)"}},{"use":{"es":"Insertos en carbono","en":"Inserts in carbon"},"glue":{"es":"Termofusible de baja temperatura (calentando solo la punta) o epoxi para insertos; sigue al fabricante del tubo","en":"Low-temperature hot melt (heating only the point) or insert epoxy; follow the shaft maker"}},{"use":{"es":"Culatines cónicos y exteriores","en":"Tapered and over nocks"},"glue":{"es":"Pegamento de emplumar o una gota de cianoacrilato","en":"Fletching cement or a drop of cyanoacrylate"}},{"use":{"es":"Culatines a presión","en":"Press-fit nocks"},"glue":{"es":"Sin pegamento (como mucho una gota pequeña)","en":"No glue (at most a small drop)"}}],"tuning":{"steps":[{"title":{"es":"Revisar el arco","en":"Check the bow setup"},"text":{"es":"Ajusta la altura de cuerda (fistmele) a la que recomienda el fabricante y coloca el punto de enfleche unos 1–1,5 cm por encima de la perpendicular a la repisa.","en":"Set the brace height (fistmele) to the maker's recommendation and place the nocking point about 1–1.5 cm (3/8–1/2 in) above square to the shelf."},"tip":{"es":"Usa una escuadra de arco (T) para medir; no cambies nada del arco durante la prueba.","en":"Use a bow square to measure; do not change anything on the bow during the test."}},{"title":{"es":"Preparar flechas de prueba","en":"Prepare test arrows"},"text":{"es":"Monta 3–6 flechas emplumadas y 1–2 astiles desnudos (sin plumas) idénticos y algo largos. En madera, fija las puntas con termofusible para poder cambiarlas.","en":"Build 3–6 fletched arrows and 1–2 identical bare shafts (no feathers), left a bit long. On wood, fit points with hot melt so you can change them."},"tip":{"es":"Compensa el peso de las plumas en el astil desnudo con un poco de cinta.","en":"Make up the feathers' weight on the bare shaft with a little tape."}},{"title":{"es":"Tirar a corta distancia","en":"Shoot at short range"},"text":{"es":"A unos 10 m, tira las emplumadas y después los astiles desnudos al mismo punto, con tu técnica normal.","en":"From about 10 m (10 yd), shoot the fletched arrows, then the bare shafts at the same spot, with your normal form."},"tip":{"es":"Calienta antes: si la técnica falla, la prueba miente. Repite varias veces.","en":"Warm up first: if your form is off, the test lies. Repeat several times."}},{"title":{"es":"Corregir primero la altura","en":"Fix vertical first"},"text":{"es":"Si el astil desnudo impacta más bajo que el grupo, el punto de enfleche está alto: bájalo. Si impacta más alto, súbelo.","en":"If the bare shaft hits lower than the group, the nocking point is too high: lower it. If it hits higher, raise it."},"tip":{"es":"Mueve el punto de enfleche en pasos de 1–2 mm.","en":"Move the nocking point in 1–2 mm steps."}},{"title":{"es":"Leer el spine (izquierda/derecha)","en":"Read spine (left/right)"},"text":{"es":"Arquero diestro: desnudo a la izquierda del grupo = flecha rígida; a la derecha = flecha blanda. Arquero zurdo: al revés.","en":"Right-handed archer: bare shaft left of the group = stiff; right = weak. Left-handed archer: the reverse."},"tip":{"es":"Fíjate también en el ángulo con que queda clavada: la cola señala hacia el mismo error.","en":"Also note the angle it sticks in the target: the tail leans toward the same error."}},{"title":{"es":"Ajustar el spine dinámico","en":"Adjust dynamic spine"},"text":{"es":"Flecha rígida: punta más pesada, flecha más larga o spine más bajo. Flecha blanda: punta más ligera, acortar 0,5 cm cada vez o spine más alto.","en":"Stiff: heavier point, longer arrow or lower spine. Weak: lighter point, shorten 0.5 cm (1/4 in) at a time, or higher spine."},"tip":{"es":"Cambia una sola cosa cada vez. En madera, acorta antes de pegar la punta definitiva.","en":"Change one thing at a time. On wood, shorten before gluing the final point."}},{"title":{"es":"Alejarse para afinar","en":"Step back to fine-tune"},"text":{"es":"Cuando el desnudo agrupe con las emplumadas a 10 m, repite a 15 y 20 m. Cuanto más lejos, más se nota el error.","en":"Once the bare shaft groups with the fletched arrows at 10 m, repeat at 15 and 20 m. The farther away, the more the error shows."},"tip":{"es":"Un pequeño error a distancia se corrige con cambios pequeños.","en":"A small error at distance needs only small changes."}},{"title":{"es":"Prueba de papel (opcional)","en":"Paper test (optional)"},"text":{"es":"Tira a través de un papel tenso a 1,5–2 m. Desgarro con la cola alta = punto de enfleche alto; baja = bajo. Diestro con dedos: cola a la izquierda = rígida; a la derecha = blanda.","en":"Shoot through tight paper from 1.5–2 m. Tear with the tail high = nocking point high; low = low. Right-handed finger shooter: tail left = stiff; right = weak."},"tip":{"es":"Con dedos y arco tradicional el papel es orientativo; el astil desnudo es más fiable.","en":"With fingers and a traditional bow paper is only a guide; the bare shaft is more reliable."}},{"title":{"es":"Anotar y fabricar el juego","en":"Record and build the set"},"text":{"es":"Apunta spine, longitud, peso de punta, peso total y FOC. Construye el resto del juego exactamente igual.","en":"Write down spine, length, point weight, total weight and FOC. Build the rest of the set exactly the same."},"tip":{"es":"FOC % = (punto de equilibrio − longitud/2) ÷ longitud × 100. Un 7–15 % es habitual en tiro; más en caza.","en":"FOC % = (balance point − length/2) ÷ length × 100. 7–15% is typical for target; more for hunting."}}]},"glossary":[{"term":{"es":"Astil / vástago","en":"Shaft"},"def":{"es":"Cuerpo de la flecha, sin punta, culatín ni plumas.","en":"The body of the arrow, without point, nock or fletching."}},{"term":{"es":"Culatín","en":"Nock"},"def":{"es":"Pieza de la cola con la ranura donde entra la cuerda.","en":"The rear piece with the slot that takes the string."}},{"term":{"es":"Culatín cónico","en":"Tapered nock"},"def":{"es":"Se pega sobre un cono hecho con el conificador (cuchilla corta) en astiles de madera.","en":"Glued over a taper cut with the taper tool (short blade) on wood shafts."}},{"term":{"es":"Culatín exterior","en":"Over nock / outside nock"},"def":{"es":"Se pega por fuera del extremo recto del astil.","en":"Glued over the straight end of the shaft."}},{"term":{"es":"Culatín interior (a presión)","en":"Inside / press-fit nock"},"def":{"es":"Entra a presión dentro de un tubo de carbono, aluminio o fibra.","en":"Pushes into a carbon, aluminium or fiberglass tube."}},{"term":{"es":"Culatín pin","en":"Pin nock"},"def":{"es":"Culatín que encaja sobre un casquillo (pin) pegado en el tubo; protege el astil de impactos.","en":"A nock that fits over a pin bushing glued into the tube; protects the shaft from impacts."}},{"term":{"es":"Punta cónica (de encolar)","en":"Taper (glue-on) point"},"def":{"es":"Punta que se pega sobre un cono de unos 5° en astiles de madera.","en":"A point glued over a ~5° taper on wood shafts."}},{"term":{"es":"Inserto","en":"Insert"},"def":{"es":"Casquillo pegado dentro del tubo donde se enrosca la punta.","en":"A sleeve glued inside the tube that the point screws into."}},{"term":{"es":"Outsert / half-out","en":"Outsert / half-out"},"def":{"es":"Casquillo que va por fuera del tubo (outsert) o mitad dentro y mitad fuera (half-out); refuerza la punta.","en":"A sleeve that fits over the tube (outsert) or half in, half out (half-out); reinforces the tip."}},{"term":{"es":"Footing","en":"Footing"},"def":{"es":"Refuerzo de madera dura o metal en la parte delantera de la flecha; más resistencia y FOC.","en":"Hardwood or metal reinforcement at the front of the arrow; more strength and FOC."}},{"term":{"es":"Spine","en":"Spine"},"def":{"es":"Rigidez del astil a la flexión. En madera se expresa en libras; en carbono y aluminio, como deflexión (p. ej. 500).","en":"The shaft's resistance to bending. Wood is rated in pounds; carbon and aluminium as deflection (e.g. 500)."}},{"term":{"es":"Spine estático / dinámico","en":"Static / dynamic spine"},"def":{"es":"Estático: el que se mide en el medidor. Dinámico: cómo se comporta al disparar, según longitud, peso de punta y arco.","en":"Static: measured on a tester. Dynamic: how it behaves when shot, depending on length, point weight and bow."}},{"term":{"es":"GPI (granos por pulgada)","en":"GPI (grains per inch)"},"def":{"es":"Peso del astil por pulgada de longitud; sirve para comparar astiles.","en":"Shaft weight per inch of length; used to compare shafts."}},{"term":{"es":"GPP (granos por libra)","en":"GPP (grains per pound)"},"def":{"es":"Peso total de la flecha dividido por la potencia del arco. En tradicional se recomienda no bajar de unos 8–9 GPP.","en":"Total arrow weight divided by draw weight. For traditional bows, staying above about 8–9 GPP is advised."}},{"term":{"es":"Grano (gr)","en":"Grain (gr)"},"def":{"es":"Unidad de peso en tiro con arco: 1 g = 15,43 granos.","en":"Archery weight unit: 1 g = 15.43 grains."}},{"term":{"es":"FOC (equilibrio delantero)","en":"FOC (front of centre)"},"def":{"es":"Cuánto adelantado está el punto de equilibrio respecto al centro de la flecha, en %.","en":"How far forward the balance point is from the arrow's centre, in %."}},{"term":{"es":"Altura de cuerda (fistmele)","en":"Brace height (fistmele)"},"def":{"es":"Distancia entre la cuerda y el punto más profundo de la empuñadura con el arco montado.","en":"Distance from the string to the deepest point of the grip on a strung bow."}},{"term":{"es":"Apertura","en":"Draw length"},"def":{"es":"Distancia a la que tensas la cuerda; la flecha mide apertura + 2,5 cm.","en":"How far you draw the string; arrow length is draw length + 2.5 cm (1 in)."}},{"term":{"es":"AMO / ATA","en":"AMO / ATA"},"def":{"es":"Normas de la industria de arquería para medir potencia, apertura, spine y longitud de cuerda.","en":"Archery industry standards for measuring draw weight, draw length, spine and string length."}},{"term":{"es":"Punto de enfleche","en":"Nocking point"},"def":{"es":"Marca o tope en la cuerda que fija la altura del culatín.","en":"A marker or stop on the string that sets the nock height."}},{"term":{"es":"Repisa (shelf)","en":"Shelf"},"def":{"es":"Corte horizontal de la ventana del arco donde se apoya la flecha en tiro tradicional.","en":"The horizontal cut in the bow window where the arrow rests in traditional shooting."}},{"term":{"es":"Reposaflechas","en":"Arrow rest"},"def":{"es":"Soporte (pegado o mecánico) donde apoya la flecha; con vanes conviene un reposaflechas elevado.","en":"A support (stick-on or mechanical) that holds the arrow; vanes need a raised rest."}},{"term":{"es":"Paradoja del arquero","en":"Archer's paradox"},"def":{"es":"La flecha se flexiona al salir y rodea la empuñadura; por eso el spine debe ser el adecuado.","en":"The arrow flexes as it leaves and bends around the riser; this is why spine must match."}},{"term":{"es":"Pluma guía (índice)","en":"Cock feather (index feather)"},"def":{"es":"Pluma de distinto color, perpendicular a la ranura del culatín, que va hacia fuera del arco.","en":"The odd-coloured feather, perpendicular to the nock slot, pointing away from the bow."}},{"term":{"es":"Ala izquierda / derecha (LW/RW)","en":"Left wing / right wing (LW/RW)"},"def":{"es":"Lado del ave de donde sale la pluma; define el sentido de giro. Nunca se mezclan.","en":"Which wing the feather comes from; sets the spin direction. Never mix them."}},{"term":{"es":"Emplumado recto","en":"Straight fletching"},"def":{"es":"Plumas paralelas al astil; menos estabilización.","en":"Feathers parallel to the shaft; least stabilisation."}},{"term":{"es":"Emplumado offset (desplazado)","en":"Offset fletching"},"def":{"es":"Plumas rectas pero ligeramente en ángulo; buen compromiso.","en":"Straight feathers set at a slight angle; a good compromise."}},{"term":{"es":"Emplumado helicoidal","en":"Helical fletching"},"def":{"es":"Plumas curvadas siguiendo una hélice; máximo giro y estabilidad, algo más de resistencia al aire.","en":"Feathers curved along a helix; most spin and stability, slightly more drag."}},{"term":{"es":"Emplumadora","en":"Fletching jig"},"def":{"es":"Útil que sujeta astil y pluma para pegarla siempre en la misma posición.","en":"A tool that holds shaft and feather to glue it in the same position every time."}},{"term":{"es":"Conificador","en":"Taper tool"},"def":{"es":"Afilador con dos cuchillas: larga para la punta (~5°) y corta para el culatín (~11°).","en":"A sharpener with two blades: long for the point (~5°) and short for the nock (~11°)."}},{"term":{"es":"Pluma escudo / parabólica / banana","en":"Shield / parabolic / banana cut"},"def":{"es":"Perfiles de recorte de la pluma: escudo (con muesca), parabólica (curva suave), banana (baja y alargada).","en":"Feather trim profiles: shield (notched), parabolic (smooth curve), banana (low and long)."}},{"term":{"es":"Flu-flu","en":"Flu-flu"},"def":{"es":"Flecha con plumas grandes en espiral que frenan rápido; para tiro aéreo o caza menor.","en":"Arrow with large spiral feathers that slow it quickly; for aerial targets or small game."}},{"term":{"es":"Crown dip","en":"Crown dip"},"def":{"es":"Baño de laca de color en la zona del culatín y las plumas.","en":"A coloured lacquer dip over the nock and fletching area."}},{"term":{"es":"Cresting","en":"Cresting"},"def":{"es":"Anillos pintados que decoran e identifican las flechas.","en":"Painted rings that decorate and identify arrows."}},{"term":{"es":"Wrap","en":"Wrap"},"def":{"es":"Vinilo adhesivo enrollado en la zona de las plumas.","en":"An adhesive vinyl sleeve rolled onto the fletching area."}},{"term":{"es":"Entorchado","en":"Thread binding"},"def":{"es":"Vueltas de hilo en los extremos de las plumas (o en culatín y punta) fijadas con pegamento.","en":"Turns of thread at feather ends (or nock and point) fixed with glue."}},{"term":{"es":"Veta / contraveta","en":"Grain / across the grain"},"def":{"es":"Dirección de las fibras de la madera. El culatín se coloca a contraveta: ranura perpendicular a la veta.","en":"Direction of the wood fibres. The nock goes across the grain: slot perpendicular to the grain lines."}},{"term":{"es":"Astil desnudo","en":"Bare shaft"},"def":{"es":"Flecha sin plumas que se usa para afinar el spine y el punto de enfleche.","en":"An unfletched arrow used to tune spine and nocking point."}},{"term":{"es":"Prueba de flexión","en":"Flex test"},"def":{"es":"Doblar suavemente la flecha y escuchar/mirar si cruje o se agrieta antes de tirar.","en":"Gently bending the arrow to listen/look for cracks before shooting."}},{"term":{"es":"Escuadrador","en":"Squaring tool"},"def":{"es":"Útil que deja el extremo del tubo plano y perpendicular.","en":"A tool that makes the tube end flat and perpendicular."}},{"term":{"es":"Sierra de flechas","en":"Arrow saw"},"def":{"es":"Sierra con disco abrasivo de alta velocidad para cortar carbono, aluminio y fibra.","en":"A high-speed abrasive-wheel saw for cutting carbon, aluminium and fiberglass."}},{"term":{"es":"Termofusible","en":"Hot melt"},"def":{"es":"Pegamento que se funde con calor; permite desmontar puntas calentándolas.","en":"Heat-melted glue; lets you remove points by heating them."}},{"term":{"es":"Swage (extremo estampado)","en":"Swage"},"def":{"es":"Cono formado en el extremo de algunos tubos de aluminio para pegar el culatín.","en":"A taper formed on the end of some aluminium tubes to glue the nock onto."}},{"term":{"es":"Punta de campo / punta de caza","en":"Field point / broadhead"},"def":{"es":"Punta de entrenamiento con forma de bala / punta con cuchillas para caza.","en":"Bullet-shaped practice point / bladed hunting head."}},{"term":{"es":"Spinner (girador)","en":"Arrow spinner"},"def":{"es":"Soporte con rodamientos para hacer girar la flecha, comprobar rectitud y hacer cresting.","en":"A bearing cradle to spin an arrow, check straightness and do cresting."}},{"term":{"es":"Runout (veta que se escapa)","en":"Grain runout"},"def":{"es":"Veta que sale en diagonal por la superficie del astil; punto débil.","en":"Grain lines that exit diagonally through the shaft surface; a weak spot."}}]};
